        where state in (0,1,2,3,4,5,6,7)
        and (
            s.user_id = #{uid}
            OR s.first_person_id = #{uid}
            OR s.second_person_id = #{uid}
            OR s.third_person_id = #{uid}
            OR s.fourth_person_id = #{uid}
            OR s.members LIKE CONCAT('%"', #{uid}, '"%')
        )
         and mingcheng like concat('%', #{mingcheng}, '%')
             and huopishijain = #{huopishijain}
             and fenlei = #{fenlei}
         and YEAR(DATE_ADD(s.huopishijain,INTERVAL 1 MONTH)) = #{year}
        order by
        case
--         草稿箱
        when state = 0 then 1
--         被驳回
        when state in (3,5,7) then 2
--         审核中
        when state in (1,2,4) then 3
--         已完结
        when state in (6) then  4
        end,
        createtime desc


        where (s.user_id = #{uid} or d.dept_id = #{deptId})
        and u.user_name like concat('%', #{xingming}, '%')
         and mingcheng like concat('%', #{mingcheng}, '%')
         and huopishijain = #{huopishijain}
         and fenlei = #{fenlei}
         and YEAR(DATE_ADD(s.huopishijain,INTERVAL 1 MONTH)) = #{year}
        ${params.dataScope}
        order by
        case
--         待教研室审核
        when state = 1 then 1
--         教研室通过
        when state in (2) then 2

        when state  = 0 then 3
        end,
        createtime desc

