select p.dept_name yname, d.dept_name dname, u.login_name login_name, u.user_name userName, s.mingcheng, s.jifen, s.state, s.huopishijain from sci_zhuanliruanzhu s left join sys_user u on s.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id = p.dept_id where 1=1 and s.jifen !='0'
AND p.dept_id = #{college}
AND d.dept_id = #{major}
AND u.user_id = #{teacherName}
and s.createtime >= #{startTime}
and s.createtime <= #{endTime}
and s.mingcheng like concat('%', #{topicName}, '%')
AND s.state in (3,5,7,0)
AND s.state in (1,2,4)
AND s.state in (6)
AND YEAR(DATE_ADD(s.huopishijain, INTERVAL 1 MONTH)) = #{year}
${_dataScope}
order by yname asc,dname asc,u.login_name asc
